#include <query/executor/ExecutorUtils.h>
#include <query/executor/StateInternal.h>
namespace mldp_pvxs_driver::query::executor { namespace { class State final : public ExecutionStateBase { public: State(plan::PhysicalLimit node, const ExecutionContext& context, QueryStats& stats) : ExecutionStateBase(context, stats), node_(std::move(node)) { addChild(node_.input); } std::string_view typeName() const noexcept override { return "LimitExecutionState"; } RecordBatches execute() override { return applyLimit(childAt(0).execute(), node_.limit); } private: plan::PhysicalLimit node_; }; } std::unique_ptr<IExecutionState> makeLimitExecutionState(const plan::PhysicalLimit& node, const plan::PhysicalNodePtr&, const ExecutionContext& context, QueryStats& stats) { return std::make_unique<State>(node, context, stats); } }
